const input = $input.first().json;

const candidateArsenal = {
  name: 'Shikhar Thakur',
  location: 'Nürnberg, Germany',
  phone: '+49 15510180516',
  email: 'shikhar.thakur@fau.de',
  linkedin: 'linkedin.com/in/shikhar2404',
  degree: 'M.Sc. International Information Systems (Wirtschaftsinformatik), FAU Erlangen-Nürnberg — 3rd semester, English-taught',
  languages: {
    english: 'C1 / Fluent',
    german: 'B1 — actively learning, honest disclosure required in every letter'
  },
  academic_modules: [
    'Process Analytics & BPM: business process lifecycles, process mining, event log analysis, bottleneck/operational-efficiency optimization',
    'Cloud & Distributed Systems: GCP deployment, client-server architecture, WebSockets, REST APIs'
  ],
  proof_points: [
    {
      id: 'taskorbit',
      label: 'TaskOrbit (FAU AMOS open-source project, Prof. Dr. Riehle)',
      facts: '41 commits; asynchronous agentic AI orchestration pipeline; FastAPI (Python) backend; real-time WebSockets; Syft SBOM compliance; React/TypeScript frontend; deployed on GCP; worked in an international Scrum team.',
      bridges: [
        'Real-time IoT/telemetry & fleet-monitoring pipelines (via async orchestration + WebSockets)',
        'Cloud-based service architecture and deployment experience (via GCP) — transferable fundamentals to AWS/Azure',
        'Software supply-chain security awareness (via Syft SBOM compliance)',
        'Cross-functional agile collaboration across time zones (via international Scrum team)'
      ]
    },
    {
      id: 'fytly',
      label: 'FytlY (Co-Founder, 2023–2024, shipped to App Store)',
      facts: '61-screen cross-platform React Native app; OpenAI API integration; HealthKit/Health Connect live telemetry; WebSockets under production load; selected by YSR Capital Munich with a conditional funding offer.',
      bridges: [
        'End-to-end cross-platform application development shipped under real production constraints',
        'Live sensor/telemetry data handling (HealthKit/Health Connect parallels industrial sensor telemetry)',
        'AI/ML API integration experience — relevant for AI-adjacent or automation-adjacent roles'
      ]
    },
    {
      id: 'process_analytics',
      label: 'Process Analytics & BPM coursework',
      facts: 'Studied BPM lifecycles, process mining techniques, and event log structures; applied bottleneck-analysis methods to sample operational datasets.',
      bridges: [
        'Digital manufacturing / operations process optimization and bottleneck analysis',
        'Structured evaluation of workflow and ticket-handling efficiency'
      ]
    },
    {
      id: 'n8n_pipeline',
      label: 'Self-built n8n + Gemini automation pipeline',
      facts: 'Designed and built a local automation pipeline integrating LLM API calls with structured workflow logic to automate document generation end-to-end.',
      bridges: [
        'Practical workflow-automation and low-code integration experience',
        'Comfort building and maintaining ticket/process automation tooling'
      ]
    },
    {
      id: 'research_paper',
      label: 'FAU seminar research: Productivity Paradox of Generative AI in Software Development',
      facts: 'Analyzed complexity displacement and architectural drift caused by generative AI tools in software engineering workflows.',
      bridges: [
        'Analytical, critical-thinking approach to evaluating AI/automation tooling trade-offs',
        'Relevant for roles involving AI tool governance, evaluation, or rollout'
      ]
    }
  ],
  banned_phrases: [
    'leverage', 'cutting-edge', 'passionate about', 'seamlessly', 'revolutionize',
    'dynamic', 'synergy', 'results-driven', 'self-starter', 'team player',
    'fast-paced environment', 'out-of-the-box', 'hit the ground running'
  ]
};

const rawJobPage = input['raw_job_page'] || input['Paste Full Job Page Here'] || '';
const outputLanguage = input['output_language'] || input['Output Language'] || 'German B1';

const extractPrompt = `You are a precise, literal information-extraction engine. You read a raw job-posting page dump and output ONLY a single valid JSON object. Do not include markdown code fences, explanations, or any text outside the JSON object. If a field cannot be found, use null (or an empty array for array fields) — never guess or fabricate a value.

Extract structured metadata following these field rules:
- company_name: exact company name.
- job_title: copy verbatim, exactly as the posting's main heading, in its original language. Do NOT translate it.
- job_id: only if explicitly labeled (e.g. "Job ID", "Stellen-ID", "514955"). Else null.
- location: city name, e.g. "Erlangen" or "Nürnberg".
- employment_type: infer from title/context (Werkstudent, Praktikum, Vollzeit, Abschlussarbeit, Duales Studium, Other).
- industry_sector: infer company's actual industry (e.g. "Rail & Mobility", "Automotive", "Energy", "Software/IT Consulting").
- domain_function: write ONE plain sentence describing what this role does day-to-day in functional terms.
- team_context: extract any specific department, plant, product, or platform names mentioned (e.g. "SMO plants", "Insights Hub", "Industrial Edge"). Null if none.
- responsibilities: array of actual duty/responsibility lines from the posting (near-verbatim).
- requirements: array of actual requirement lines from the posting (near-verbatim).
- key_tech: array of every named technology, language, tool, or platform mentioned.
- language_requirement: { "german_level_required": "none_specified | basic | conversational | business_fluent", "english_level_required": "none_specified | basic | conversational | business_fluent", "raw_snippet": "literal sentence about language" }
- contact_person_full: extract only if named recruiter is explicitly given.
- contact_gender: infer ONLY from explicit German titles ("Herr"/"Frau") directly next to name (male | female | unknown).
- contact_lastname: last name only if found, else null.
- company_mission_snippet: paraphrase company stated purpose in <=25 words, if present. Else null.
- flags: array with any of ["missing_contact", "missing_job_id", "language_mismatch_risk", "bilingual_posting"].

RAW PAGE DUMP:
"""
${rawJobPage}
"""`;

return {
  json: {
    raw_job_page: rawJobPage,
    output_language: outputLanguage,
    candidateArsenal,
    extract_prompt: extractPrompt
  }
};

function extractJsonFromLLMOutput(raw) {
  if (!raw) return null;
  let text = typeof raw === 'string' ? raw : JSON.stringify(raw);
  text = text.replace(/```json/gi, '').replace(/```/g, '').trim();
  try {
    return JSON.parse(text);
  } catch (e) {
    const match = text.match(/\{[\s\S]*\}/);
    if (match) {
      try { return JSON.parse(match[0]); } catch (e2) { return null; }
    }
    return null;
  }
}

const item = $input.first().json;
const ctx = $('Inject Context').first().json;
const rawLLMOutput = item.text ?? item.output ?? item.content ?? item;

const metadata = extractJsonFromLLMOutput(rawLLMOutput) || {
  company_name: 'Unternehmen',
  job_title: 'Werkstudent',
  job_id: null,
  employment_type: 'Werkstudent',
  industry_sector: 'Technology',
  domain_function: 'Unterstützung im IT-Bereich',
  team_context: null,
  responsibilities: [],
  requirements: [],
  key_tech: [],
  contact_person_full: null,
  contact_gender: 'unknown',
  contact_lastname: null,
  flags: ['missing_contact']
};

let salutationDE, salutationEN;
if (metadata.contact_lastname && metadata.contact_gender === 'male') {
  salutationDE = `Sehr geehrter Herr ${metadata.contact_lastname},`;
  salutationEN = `Dear Mr. ${metadata.contact_lastname},`;
} else if (metadata.contact_lastname && metadata.contact_gender === 'female') {
  salutationDE = `Sehr geehrte Frau ${metadata.contact_lastname},`;
  salutationEN = `Dear Ms. ${metadata.contact_lastname},`;
} else if (metadata.contact_person_full) {
  salutationDE = `Sehr geehrte Damen und Herren,`;
  salutationEN = `Dear ${metadata.contact_person_full},`;
} else {
  salutationDE = `Sehr geehrte Damen und Herren,`;
  salutationEN = `Dear Hiring Team,`;
}

const flags = Array.isArray(metadata.flags) ? [...metadata.flags] : [];
if (metadata.language_requirement?.german_level_required === 'business_fluent') {
  flags.push('language_mismatch_risk');
}
if (!metadata.job_id) flags.push('missing_job_id');
if (!metadata.contact_person_full) flags.push('missing_contact');

const isGerman = (ctx.output_language || '').toLowerCase().includes('german');

const stage5Prompt = `You are helping a candidate write authentic, non-generic cover-letter bullet points.
Your ONLY job is to connect the candidate's REAL, VERIFIED experience to the SPECIFIC function of the target role — never list technologies without explaining why they matter for this role's actual day-to-day work.

RULES:
1. Select the 3 requirements/responsibilities with the STRONGEST honest connection to the candidate's proof points from the given pre-approved bridges array. Do not invent a bridge that isn't listed.
2. Bullet structure: [concrete proof point / project name] + [specific technical action taken, real facts only] + [explicit explanation of why this matters for THIS role's actual function — reference domain_function/team_context by name where natural].
3. NEVER end a bullet on a bare technology list. Always land on functional relevance to the target role.
4. BANNED PHRASES (NEVER USE): leverage, cutting-edge, passionate about, seamlessly, revolutionize, dynamic, synergy, results-driven, self-starter, team player, fast-paced environment, out-of-the-box, hit the ground running.
5. If bridging cloud experience to a role requiring AWS/Azure, phrase honestly as "transferable cloud fundamentals from GCP" — never claim direct AWS/Azure production experience.
6. Vary sentence openers across the 3 bullets.
7. Language Register: ${isGerman ? 'German B1 (simple, authentic, clear student voice, short sentences)' : 'English C1 (natural, confident professional English)'}.
8. Write one opening_hook (1-2 sentences) referencing the company's actual mission/team/domain_function to replace generic openers like "I am pleased to apply."
9. Return ONLY a single valid JSON object (no markdown code fences) with keys: opening_hook, bullet_1, bullet_2, bullet_3, bridge_used.

JOB METADATA:
${JSON.stringify(metadata, null, 2)}

CANDIDATE PROOF POINTS & BRIDGES:
${JSON.stringify(ctx.candidateArsenal.proof_points, null, 2)}`;

return [{
  json: {
    ...ctx,
    metadata,
    salutationDE,
    salutationEN,
    flags,
    stage5_prompt: stage5Prompt
  }
}];

function extractJsonFromLLMOutput(raw) {
  if (!raw) return null;
  let text = typeof raw === 'string' ? raw : JSON.stringify(raw);
  text = text.replace(/```json/gi, '').replace(/```/g, '').trim();
  try {
    return JSON.parse(text);
  } catch (e) {
    const match = text.match(/\{[\s\S]*\}/);
    if (match) {
      try { return JSON.parse(match[0]); } catch (e2) { return null; }
    }
    return null;
  }
}

const item = $input.first().json;
const ctx = $('Parse Metadata & Build Bullet Prompt').first().json;
const rawBulletOutput = item.text ?? item.output ?? item.content ?? item;
const bullets = extractJsonFromLLMOutput(rawBulletOutput) || {
  opening_hook: 'Die Verbindung von IT und industriellen Prozessen ist der Schwerpunkt meines Profils.',
  bullet_1: 'Im FAU-Projekt TaskOrbit habe ich Backend- und Schnittstellenstrukturen mit FastAPI und WebSockets implementiert.',
  bullet_2: 'Als Co-Founder von FytlY habe ich eine 61-Screen Cross-Platform Anwendung unter realen Produktionsbedingungen umgesetzt.',
  bullet_3: 'Durch mein Studium im Bereich Process Analytics analysiere ich betriebliche Workflows und Bottlenecks systematisch.',
  bridge_used: ['taskorbit', 'fytly', 'process_analytics']
};

const isGerman = (ctx.output_language || '').toLowerCase().includes('german');
const metadata = ctx.metadata;
const today = new Date().toLocaleDateString(isGerman ? 'de-DE' : 'en-GB', {
  day: '2-digit', month: '2-digit', year: 'numeric'
});

const subjectLine = isGerman
  ? `Bewerbung als ${metadata.job_title}${metadata.job_id ? ` – ID: ${metadata.job_id}` : ''}`
  : `Application for ${metadata.job_title}${metadata.job_id ? ` — ID: ${metadata.job_id}` : ''}`;

const salutation = isGerman ? ctx.salutationDE : ctx.salutationEN;

const bridgingParagraph = isGerman
  ? `Mein Studium an der FAU verbindet technische Informatik mit betriebswirtschaftlichen Prozessen. Dadurch arbeite ich mich schnell in neue Plattformen und Tools ein und bringe mich lösungsorientiert im Team ein.`
  : `My degree bridges computer science with business processes, allowing me to quickly adapt to new tools and technologies and contribute in a solution-oriented way.`;

const languageDisclosure = isGerman
  ? `Mein Masterstudium wird auf Englisch unterrichtet. Ich lerne aktiv Deutsch und besitze aktuell das Niveau B1, das ich im Arbeitsalltag gerne weiter vertiefen möchte.`
  : `My Master's is taught in English. I actively learn German (currently B1) and look forward to improving further in a professional environment.`;

const employmentClosingMap = {
  Werkstudent: {
    de: 'Ich bin an der FAU immatrikuliert, ab sofort verfügbar und kann meine Wochenstunden flexibel um mein Studium herum gestalten.',
    en: 'I am enrolled at FAU, available immediately, and can flexibly arrange my weekly hours around my studies.'
  },
  Praktikum: {
    de: 'Ich bin an der FAU immatrikuliert und für den gesamten Praktikumszeitraum verfügbar.',
    en: 'I am enrolled at FAU and available for the full internship duration.'
  },
  Abschlussarbeit: {
    de: 'Ich bin an der FAU immatrikuliert und freue mich darauf, das Thema meiner Abschlussarbeit mit Ihrem Team abzustimmen.',
    en: 'I am enrolled at FAU and look forward to aligning my thesis topic with your team.'
  },
  Vollzeit: {
    de: 'Ich schließe mein Studium zeitnah ab und stehe für eine Vollzeitanstellung zur Verfügung.',
    en: 'I am completing my studies shortly and available for full-time employment.'
  }
};

const empType = metadata.employment_type || 'Werkstudent';
const employmentClosing = (employmentClosingMap[empType] || employmentClosingMap.Werkstudent)[isGerman ? 'de' : 'en'];

const signOff = isGerman
  ? `Über eine Einladung zum Vorstellungsgespräch würde ich mich sehr freuen.\n\nMit freundlichen Grüßen\n\nShikhar Thakur`
  : `I would be very pleased to receive an invitation to an interview.\n\nSincerely,\n\nShikhar Thakur`;

const letter = [
  `Shikhar Thakur`,
  `Nürnberg, Deutschland | +49 15510180516 | shikhar.thakur@fau.de | linkedin.com/in/shikhar2404`,
  ``,
  `${metadata.company_name}`,
  `Human Resources / Recruiting`,
  `${metadata.location || 'Nürnberg'}, den ${today}`,
  ``,
  subjectLine,
  ``,
  salutation,
  ``,
  bullets.opening_hook,
  ``,
  `• ${bullets.bullet_1}`,
  `• ${bullets.bullet_2}`,
  `• ${bullets.bullet_3}`,
  ``,
  bridgingParagraph,
  ``,
  languageDisclosure,
  ``,
  employmentClosing,
  ``,
  signOff
].join('\n');

const cleanCompany = (metadata.company_name || 'Company').replace(/[^a-zA-Z0-9]/g, '_');
const cleanJobId = (metadata.job_id || 'Role').replace(/[^a-zA-Z0-9]/g, '_');
const roleFolder = empType;
const filename = `Anschreiben_Shikhar_Thakur_${cleanCompany}_${cleanJobId}`;

return [{
  json: {
    ...ctx,
    bullets,
    letter,
    filename,
    cleanCompany,
    roleFolder,
    flagsForReview: ctx.flags
  }
}];

const fs = require('fs');
const data = $input.first().json;

const html = `<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  @page { 
    size: A4; 
    margin: 25mm 20mm 20mm 25mm; 
  }
  body {
    font-family: Arial, Helvetica, sans-serif;
    font-size: 10.5pt;
    line-height: 1.42;
    color: #111;
    margin: 0;
    white-space: pre-line;
  }
</style>
</head>
<body>${data.letter.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}</body>
</html>`;

const htmlPath = `/tmp/${data.filename}.html`;

// Organized target folders
const organizedDir = `/Users/shikharthakur/Documents/n8n/companies/${data.cleanCompany}/${data.roleFolder}`;
fs.mkdirSync(organizedDir, { recursive: true });

const organizedPdfPath = `${organizedDir}/${data.filename}.pdf`;
const downloadsPdfPath = `/Users/shikharthakur/Downloads/${data.filename}.pdf`;

fs.writeFileSync(htmlPath, html, 'utf8');

return { 
  json: { 
    ...data, 
    html_path: htmlPath, 
    organized_pdf_path: organizedPdfPath,
    downloads_pdf_path: downloadsPdfPath,
    organized_dir: organizedDir
  } 
};

const { execSync } = require('child_process');
const fs = require('fs');
const data = $input.first().json;

try {
  // Render PDF using --headless=new and --no-pdf-header-footer to prevent file:/// and dates from appearing
  execSync(
    `/Applications/Microsoft\\ Edge.app/Contents/MacOS/Microsoft\\ Edge --headless=new --disable-gpu --no-pdf-header-footer --print-to-pdf="${data.organized_pdf_path}" "file://${data.html_path}" 2>/dev/null`,
    { timeout: 20000 }
  );
  fs.copyFileSync(data.organized_pdf_path, data.downloads_pdf_path);
} catch(e) {
  // Handle Edge exit codes
}

// Read binary for Google Drive upload node
const pdfBuffer = fs.readFileSync(data.organized_pdf_path);

return [{
  json: { ...data },
  binary: {
    data: {
      data: pdfBuffer.toString('base64'),
      mimeType: 'application/pdf',
      fileName: `${data.filename}.pdf`
    }
  }
}];

